CREATE TABLE IF NOT EXISTS policies (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, status TEXT NOT NULL, summary TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS milestones (id INTEGER PRIMARY KEY AUTOINCREMENT, policy_id INTEGER NOT NULL, label TEXT NOT NULL, date TEXT, detail TEXT NOT NULL, is_verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS evidence (id INTEGER PRIMARY KEY AUTOINCREMENT, policy_id INTEGER NOT NULL, title TEXT NOT NULL, publisher TEXT NOT NULL, source_type TEXT NOT NULL, url TEXT NOT NULL, claim TEXT NOT NULL);
